function expected(job,kind='main'){
  // This is a declared-fixture membership oracle, not an AST interpreter. The
  // source index sets are known before capture; captured facts must match them.
  const rows=titleRows(job),indices=kind==='all'?null:kind==='none'?[]:Array.from({length:151},(_,index)=>index).filter(index=>{const observed=index===150?149:index;
    if(kind==='nested')return index>=1;
    if(kind==='without-missing')return observed>=2&&observed%5!==0;
    if(kind==='zero')return index===0||observed===1||observed>1&&observed%5===0;
    if(kind==='main'||kind==='cohort-one')return observed>=4&&observed%5!==0&&(kind!=='cohort-one'||observed%7===1);
    throw Error('Unknown declared fixture population '+kind);
  }),members=indices===null?null:new Set(indices.map(index=>'/items/'+String(index).padStart(4,'0'))),selected=members===null?rows:rows.filter(row=>[...members].some(suffix=>row.url.endsWith(suffix)));
  assert.equal(rows.length,152);if(kind==='main')assert.equal(selected.length,118);if(kind==='nested')assert.equal(selected.length,150);if(kind==='zero')assert.equal(selected.length,31);return ordered(selected,['main','cohort-one'].includes(kind)?'title_text':'url',['main','cohort-one'].includes(kind)?-1:1);
}
