async function refresh(){
  await libraryOpen();
  const section=await page.locator('[data-section][aria-current="page"]').getAttribute('data-section');
  assert(section,'The visible native section must own its saved-view options');
  await page.click('#'+prefix+'refresh');
  await page.waitForFunction(({key,prefix,section})=>{
    try{
      const raw=localStorage.getItem(key),expected=raw===null?[]:JSON.parse(raw).entries.filter(entry=>entry.section===section).map(entry=>entry.id);
      const actual=[...document.querySelectorAll('#'+prefix+'select option')].map(option=>option.value).filter(Boolean);
      return JSON.stringify(actual)===JSON.stringify(expected);
    }catch{return false;}
  },{key:libraryKey,prefix,section});
}
